def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Use recursion for nested objects, limit depth to avoid infinite recursion
    def _format(obj, indent_level):
        indent_str = ' ' * (indent_level * 4)
        if isinstance(obj, (list, tuple, set)):
            opening = '[' if isinstance(obj, list) else '(' if isinstance(obj, tuple) else '{'
            closing = ']' if isinstance(obj, list) else ')' if isinstance(obj, tuple) else '}'
            items = []
            for item in obj:
                items.append(_format(item, indent_level + 1))
            return f"{opening}\n{',\n'.join(' '*(indent_level+1)*4 + i for i in items)}\n{indent_str}{closing}"
        elif isinstance(obj, dict):
            opening = '{\n'
            closing = f'\n{indent_str}}}'
            items = []
            for k, v in obj.items():
                items.append(f"{' '*(indent_level+1)*4}{repr(k)}: {_format(v, indent_level+1)}")
            return f"{opening}{',\n'.join(items)}{closing}"
        else:
            if hasattr(obj, '__dict__') and not isinstance(obj, type):
                # pretty print object's attributes
                attrs = vars(obj)
                if not attrs:
                    return repr(obj)
                opening = f"{obj.__class__.__name__}(\n"
                closing = f'\n{indent_str})'
                lines = []
                for k, v in attrs.items():
                    lines.append(f"{' '*(indent_level+1)*4}{k}={_format(v, indent_level+1)}")
                return f"{opening}{',\n'.join(lines)}{closing}"
            else:
                return repr(obj)
    return _format(self, indent)
```

