from typing import List, Optional

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number < 0:
        raise ValueError("number must be non-negative")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two symbols")
    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
        result = "".join(reversed(digits))
    # Pad with the first symbol of the alphabet if padding is specified
    if padding is not None and padding > len(result):
        result = alphabet[0] * (padding - len(result)) + result
    return result
